head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16403n";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — corpUserTpCd, editAvailYn, regYn, count, disableYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16403n.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpUserTpCd", fn: function(){ return ((dma_pageContext.get("corpUserTpCd") ?? "") === '61'); } }, { id: "if_corpUserTpCd_2", fn: function(){ return ((dma_pageContext.get("corpUserTpCd") ?? "") === '62' || (dma_pageContext.get("corpUserTpCd") ?? "") === '63'); } }, { id: "if_corpUserTpCd_3", fn: function(){ return ((dma_pageContext.get("corpUserTpCd") ?? "") === '61'); } }, { id: "if_corpUserTpCd_4", fn: function(){ return ((dma_pageContext.get("corpUserTpCd") ?? "") === '62' || (dma_pageContext.get("corpUserTpCd") ?? "") === '63'); } }, { id: "c_when_77_txt", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_78", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "c_when_94", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_96", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "if_editAvailYn", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_when_90", fn: function(){ return ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'Y'); } }, { id: "c_when_111", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_113", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "if_editAvailYn_2", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_when_107", fn: function(){ return ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'N'); } }, { id: "c_otherwise_126", fn: function(){ return (!(((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'Y') || ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'N'))); } }, { id: "btn_Modify_4", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_136", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }, { id: "btn_Modify_5", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_144", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }, { id: "btn_Delete_3", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_150", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb1", fn: function () { return String((String(String(dma_eduDisclsChrg.get("bzRegNo")) == null ? '' : String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,'').length === 10 ? String(dma_eduDisclsChrg.get("bzRegNo")).replace(/[^0-9]/g,'').slice(0,3) + '-' + String(dma_eduDisclsChrg.get("bzRegNo")).replace(/[^0-9]/g,'').slice(3,5) + '-' + String(dma_eduDisclsChrg.get("bzRegNo")).replace(/[^0-9]/g,'').slice(5) : String(String(dma_eduDisclsChrg.get("bzRegNo")) == null ? '' : String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,''))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
