///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (_submitYn) {
    if (!await scwin.chk2()) {
        return;
    }
    let frm = (document.eduForm || { elements: [] });
    if ($c.util.getComponent('dma_RegisterReq').get('disclsEduApplSeq') === '69') {
        let count = (String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))));
        if (parseInt(count) >= 150) {
            await $c.win.alert("교육수용인원이 초과되어 접수를 마감하였습니다.\n다음차수에 신청하여 주시기 바랍니다. 감사합니다.");
            return;
        }
    }
    if ($c.util.getComponent('dma_RegisterReq').get('disclsEduApplSeq') === '70') {
        count = (String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))));
        if (parseInt(count) >= 140) {
            await $c.win.alert("교육수용인원이 초과되어 접수를 마감하였습니다.\n다음차수에 신청하여 주시기 바랍니다. 감사합니다.");
            return;
        }
    }
    frm = (document.eduForm || { elements: [] });
    frm.action = 'eduRspn.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerResponsibilityEducation');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_submitYn) {
    const frm = (document.eduForm || { elements: [] });
    frm.action = 'eduRspn.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'modifyResponsibilityEducation');
    await scwin.tx_fn_Modify();
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @param {*} _disclsEduApplSeq _disclsEduApplSeq
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _submitYn) {
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        const frm = (document.eduForm || { elements: [] });
        $c.util.getComponent('dma_RegisterReq').set('disclsEduApplSeq', _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        frm.action = 'eduRspn.do';
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeResponsibilityEducation');
        await scwin.tx_fn_Delete();
    } else {
        return;
    }
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
