};

/**
 * @method
 * @name chk2
 * @description chk2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk2 = async function () {
    const frm = (document.eduForm || { elements: [] });
    if ((String(((dma_pageContext.get("disableYn") ?? "")) == null ? '' : ((dma_pageContext.get("disableYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("disableYn") ?? "")) == null ? '' : ((dma_pageContext.get("disableYn") ?? "")))) === 'Y') {
        if (frm.roomTpCd.value === "") {
            await $c.win.alert("간담회(식사) 참석여부를 선택해주세요.");
            roomTpCd.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk = async function () {
    const frm = (document.eduForm || { elements: [] });
    if (frm.depAirtkClssCd.value !== "") {
        if (frm.depTpCd.value !== "01" || frm.depIndvdlMvYn.value !== "N") {
            await $c.win.alert("서울&단체 이동인 경우에만 선택 가능합니다");
            depAirtkClssCd.focus();
            return false;
        }
    }
    if (frm.depReservprnTpCd.value !== "") {
        if (frm.depTpCd.value === "01") {
            await $c.win.alert("지방 출발시만  선택 가능합니다");
            depReservprnTpCd.focus();
            return false;
        }
    }
    if (frm.destAirtkClssCd.value !== "") {
        if (frm.destTpCd.value !== "01" || frm.destIndvdlMvYn.value !== "N") {
            await $c.win.alert("서울&단체 이동인 경우에만 선택가능합니다");
            destAirtkClssCd.focus();
            return false;
        }
    }
    if (frm.destReservprnTpCd.value !== "") {
        if (frm.destTpCd.value === "01") {
            await $c.win.alert("지방 출발시만  선택 가능합니다");
            destReservprnTpCd.focus();
            return false;
        }
    }
    if (frm.disclsEduEvtAddContn.value !== "") {
        if (frm.disclsEduEvtTpCd.value !== "1") {
            await $c.win.alert("골프 선택시만  작성 가능합니다");
            disclsEduEvtAddContn.focus();
            return false;
        }
    }
    return true;
};
